class SmartLightScreen extends StatefulWidget {
  const SmartLightScreen({Key? key}) : super(key: key);
  @override
  State<SmartLightScreen> createState() => _SmartLightScreenState();
}

class _SmartLightScreenState extends State<SmartLightScreen> {
  bool _isOn = true;
  double _brightness = 0.8;
  int _selectedColorIndex = 0;
  final List<Color> _colors = [Colors.yellow, Colors.blue, Colors.red, Colors.green, Colors.purple];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Living Room Light')),
      body: Padding(
        padding: const EdgeInsets.all(24.0),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Center(child: Icon(Icons.lightbulb, size: 120, color: _isOn ? _colors[_selectedColorIndex] : Colors.grey)),
            const SizedBox(height: 40),
            Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [const Text('Power', style: TextStyle(fontSize: 20, fontWeight: FontWeight.bold)), Switch(value: _isOn, onChanged: (val) { setState(() { _isOn = val; }); })]),
            const SizedBox(height: 30),
            const Text('Brightness', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
            Slider(value: _brightness, onChanged: _isOn ? (val) { setState(() { _brightness = val; }); } : null),
            const SizedBox(height: 30),
            const Text('Color', style: TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
            const SizedBox(height: 16),
            Row(
              mainAxisAlignment: MainAxisAlignment.spaceBetween,
              children: List.generate(_colors.length, (index) {
                return GestureDetector(
                  onTap: _isOn ? () { setState(() { _selectedColorIndex = index; }); } : null,
                  child: Container(width: 50, height: 50, decoration: BoxDecoration(shape: BoxShape.circle, color: _colors[index], border: Border.all(color: _selectedColorIndex == index ? Colors.black : Colors.transparent, width: 3))),
                );
              }),
            )
          ],
        ),
      ),
    );
  }
}

