class SendMoneyScreen extends StatefulWidget {
  const SendMoneyScreen({Key? key}) : super(key: key);
  @override
  State<SendMoneyScreen> createState() => _SendMoneyScreenState();
}

class _SendMoneyScreenState extends State<SendMoneyScreen> {
  String amount = '0';
  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Send Money'), elevation: 0),
      body: Column(
        children: [
          Expanded(
            flex: 2,
            child: Center(
              child: Text('\$$amount', style: const TextStyle(fontSize: 64, fontWeight: FontWeight.bold)),
            ),
          ),
          Expanded(
            flex: 3,
            child: Container(
              padding: const EdgeInsets.all(20),
              color: Colors.grey[100],
              child: GridView.builder(
                physics: const NeverScrollableScrollPhysics(),
                gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount: 3, childAspectRatio: 1.5),
                itemCount: 12,
                itemBuilder: (context, index) {
                  if (index == 9) return const SizedBox.shrink();
                  if (index == 11) return IconButton(icon: const Icon(Icons.backspace), onPressed: () { setState(() { if (amount.length > 1) amount = amount.substring(0, amount.length - 1); else amount = '0'; }); });
                  String num = index == 10 ? '0' : '${index + 1}';
                  return TextButton(onPressed: () { setState(() { if (amount == '0') amount = num; else amount += num; }); }, child: Text(num, style: const TextStyle(fontSize: 28, color: Colors.black)));
                },
              ),
            ),
          ),
          Padding(padding: const EdgeInsets.all(16.0), child: SizedBox(width: double.infinity, height: 50, child: ElevatedButton(onPressed: () {}, child: const Text('Continue'))))
        ],
      ),
    );
  }
}

